const body = $input.first().json.body || {};
const msg = body.message || {};
const from = msg.from || {};
const chat = msg.chat || {};
const text = msg.text || msg.caption || '';

const urlMatch = text.match(/https?:\/\/\S+/);
const meetingUrl = urlMatch ? urlMatch[0] : '';

const chatId = String(chat.id || '');

return [{
  json: {
    core_workflow_id: 'MEETINGS_AGENT_CORE_ID',
    trigger_source: 'telegram',
    channel: 'telegram',
    meeting_id: 'tg-' + chatId,
    meeting_url: meetingUrl,
    meeting_title: meetingUrl ? 'Solicitud via Telegram' : 'Chat via Telegram',
    meeting_date: new Date().toISOString(),
    message: text,
    transcript_text: '',
    attendees_hint: [],
    conversation_id: chatId,
    user_id: String(from.id || ''),
    metadata: {
      update_id: body.update_id || null,
      message_id: msg.message_id || null,
      username: from.username || null,
      first_name: from.first_name || null,
      chat_id: chatId,
      source: 'telegram'
    }
  }
}];

const item = $input.first().json || {};
const dispatch = item.body || item;
const chatId = item.metadata?.chat_id || item.conversation_id || '';
return [{ json: {
  status: 'bot_dispatched',
  user_message: 'Estoy enviando a Sofer a tu reunion. Te aviso cuando tenga la transcripcion lista. 🎙️',
  channel: 'telegram',
  metadata: { chat_id: chatId, dispatch_response: dispatch }
} }];

const inputItem = $input.first().json || {};
let rawText = String(inputItem.user_message || '').trim();

if (!rawText) {
  const status = String(inputItem.status || '');
  if (status === 'pending') rawText = 'Recibido. Cuando tengas la transcripcion lista, procesare la reunion.';
  else if (status === 'skipped') rawText = 'La transcripcion no cumple los requisitos minimos para procesarla. Necesito al menos 5 intervenciones con contenido de reunion.';
  else rawText = 'Procesado. Revisa los artefactos generados.';
}

// Remove accidental wrapper braces from serialized responses.
if (rawText.startsWith('{') && rawText.endsWith('}')) {
  const inner = rawText.slice(1, -1).trim();
  if (inner.length > 0) rawText = inner;
}

// Normalize list markers.
rawText = rawText
  .replace(/^\s*\*\s{2,}/gm, '\u2022 ')
  .replace(/^\s*\*\s+/gm, '\u2022 ')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

function splitByLimit(text, maxLen) {
  if (!text) return [];
  if (text.length <= maxLen) return [text];

  const parts = [];
  const paragraphs = text.split(/\n\n+/);
  let current = '';

  const flush = () => {
    if (current.trim()) parts.push(current.trim());
    current = '';
  };

  const forceSplit = (block) => {
    const lines = block.split('\n');
    let acc = '';

    const pushHard = (line) => {
      if (line.length <= maxLen) {
        if (!acc) acc = line;
        else if ((acc + '\n' + line).length <= maxLen) acc += '\n' + line;
        else {
          parts.push(acc.trim());
          acc = line;
        }
        return;
      }

      for (let i = 0; i < line.length; i += maxLen) {
        const chunk = line.slice(i, i + maxLen);
        if (acc && (acc + '\n' + chunk).length <= maxLen) acc += '\n' + chunk;
        else {
          if (acc.trim()) parts.push(acc.trim());
          acc = chunk;
        }
      }
    };

    for (const line of lines) pushHard(line);
    if (acc.trim()) parts.push(acc.trim());
  };

  for (const p of paragraphs) {
    const candidate = current ? `${current}\n\n${p}` : p;
    if (candidate.length <= maxLen) {
      current = candidate;
      continue;
    }

    if (current) flush();
    if (p.length <= maxLen) current = p;
    else forceSplit(p);
  }

  flush();
  return parts;
}

function toTelegramHtml(text) {
  const escaped = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;');

  return escaped
    .replace(/\*\*(.+?)\*\*/g, '<b>$1</b>')
    .replace(/__([^_]+)__/g, '<b>$1</b>')
    .replace(/~~(.+?)~~/g, '<s>$1</s>')
    .replace(/\*([^*\n]+)\*/g, '<i>$1</i>')
    .replace(/_((?!_)[^_\n]+)_/g, '<i>$1</i>')
    .replace(/`([^`\n]+)`/g, '<code>$1</code>')
    .replace(/\[([^\]]+)\]\(([^)]+)\)/g, '<a href="$2">$1</a>');
}

const TELEGRAM_SAFE_LIMIT = 3900;
const chunks = splitByLimit(rawText, TELEGRAM_SAFE_LIMIT);

return chunks.map((chunk, idx) => ({
  json: {
    ...inputItem,
    telegram_text: toTelegramHtml(chunk),
    telegram_parse_mode: 'HTML',
    telegram_chunk_index: idx + 1,
    telegram_chunk_total: chunks.length
  }
}));
